/**
 * SandboxesService is Sylphx Sandboxes: isolated machines leased for a bounded
 * time, granted immediately or refused with a typed reason, and destroyed
 * before anyone else can touch them.
 * Every agent-computer surface is here: exec and files, computer actions that
 * map one-to-one onto the Anthropic computer tool and OpenAI computer-use
 * actions and return the post-action screenshot in the same call, CDP, live
 * streams, and human takeover. The streaming guest protocol (E2B envd) is
 * served at `status.endpoints.guest_uri`.
 *
 * Namespace of Sylphx Sandboxes on `Sylphx`.
 */
export class SandboxesApi {
	/** The `sandbox_shapes` collection. */
	readonly sandboxShapes: SandboxShapesCollection
	/** The `pools` collection. */
	readonly pools: PoolsCollection
	/** The `leases` collection. */
	readonly leases: LeasesCollection
	/** The `lease_events` collection. */
	readonly leaseEvents: LeaseEventsCollection
	/** The `volumes` collection. */
	readonly volumes: VolumesCollection
	/** The `snapshots` collection. */
	readonly snapshots: SnapshotsCollection

	constructor(client: runtime.Client) {
		this.sandboxShapes = new SandboxShapesCollection(client)
		this.pools = new PoolsCollection(client)
		this.leases = new LeasesCollection(client)
		this.leaseEvents = new LeaseEventsCollection(client)
		this.volumes = new VolumesCollection(client)
		this.snapshots = new SnapshotsCollection(client)
	}
}

/** `sandbox_shapes` of Sylphx Sandboxes: Resource type `sandboxes.sylphx.com/Shape`. */
export class SandboxShapesCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets a shape.
	 *
	 * `GET /v1/{name=sandbox_shapes/*}` · permission `sandboxes:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetShapeRequest): Promise<Shape> {
		return this.client.call<Shape>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'sandbox_shapes/*', 'name')}`,
			responseType: 'sylphx.sandboxes.v1.Shape',
			mutation: false,
		})
	}

	/**
	 * Lists shapes.
	 *
	 * `GET /v1/sandbox_shapes` · permission `sandboxes:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListSandboxShapesRequest): Promise<ListSandboxShapesResponse> {
		return this.client.call<ListSandboxShapesResponse>({
			method: 'GET',
			path: `/v1/sandbox_shapes`,
			query: { page_size: request.pageSize, page_token: request.pageToken, filter: request.filter, order_by: request.orderBy },
			responseType: 'sylphx.sandboxes.v1.ListSandboxShapesResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListSandboxShapesRequest): AsyncGenerator<Shape> {
		let next: ListSandboxShapesRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.sandboxShapes ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}
}

/** `pools` of Sylphx Sandboxes: Resource type `sandboxes.sylphx.com/Pool`. */
