/** `lease_events` of Sylphx Sandboxes: Resource type `sandboxes.sylphx.com/LeaseEvent`. */
export class LeaseEventsCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets one lease event.
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/leases/*\/lease_events/*}` · permission `sandboxes:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetLeaseEventRequest): Promise<LeaseEvent> {
		return this.client.call<LeaseEvent>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/leases/*/lease_events/*', 'name')}`,
			responseType: 'sylphx.sandboxes.v1.LeaseEvent',
			mutation: false,
		})
	}

	/**
	 * Lists a lease's events in order. With `wait`, blocks up to that long
	 * for an event after `page_token` (long poll).
	 *
	 * `GET /v1/{parent=orgs/*\/projects/*\/envs/*\/leases/*}/lease_events` · permission `sandboxes:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListLeaseEventsRequest): Promise<ListLeaseEventsResponse> {
		return this.client.call<ListLeaseEventsResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*/leases/*', 'parent')}/lease_events`,
			query: { page_size: request.pageSize, page_token: request.pageToken, filter: request.filter, wait: request.wait },
			responseType: 'sylphx.sandboxes.v1.ListLeaseEventsResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListLeaseEventsRequest): AsyncGenerator<LeaseEvent> {
		let next: ListLeaseEventsRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.leaseEvents ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}
}

